import type { JSX } from "react";

/**
 * Refração de borda "Liquid Glass" de verdade (feDisplacementMap, não só blur) pro painel do dia,
 * os cartões de estatística e as abas Antigas/Hoje/Futuras — ver skill liquid-glass. Renderizado
 * uma vez só aqui (src/app/reservas/layout.tsx) porque os 3 filtros valem pra tela inteira; cada
 * elemento só referencia o filtro certo no próprio backdrop-filter (ver CLASSE_CARTAO_DO_DIA em
 * reservasCompartilhado.tsx e o className das abas/tiles em PainelDeReservas.tsx).
 *
 * De propósito NÃO aplicado nos cartões de reserva individuais (CartaoDeReserva) — aninhar
 * backdrop-filter dentro de um painel que já tem backdrop-filter deu artefato visual conhecido no
 * Safari/WebKit (ver comentário em CLASSE_CARTAO_DO_DIA), e são até 20 desses na tela ao mesmo
 * tempo — pesado demais pra um efeito que mal apareceria (o painel de fora já borra o fundo).
 *
 * Efeito completo (refração) só aparece no Chrome/Edge — Safari/Firefox ignoram a parte url(...) e
 * ficam só com o blur normal, sem quebrar nada (degradação automática, sem @supports).
 */
export function DefinicoesDoVidroLiquido(): JSX.Element {
  return (
    <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden="true">
      <defs>
        <filter id="vidro-painel" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispPainel" x="0" y="0" width="400" height="560" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispPainel" scale="-16" xChannelSelector="R" yChannelSelector="G" />
        </filter>
        <filter id="vidro-tile" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispTile" x="0" y="0" width="180" height="74" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispTile" scale="-14" xChannelSelector="R" yChannelSelector="G" />
        </filter>
        <filter id="vidro-abas" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispAbas" x="0" y="0" width="380" height="50" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispAbas" scale="-12" xChannelSelector="R" yChannelSelector="G" />
        </filter>
      </defs>
    </svg>
  );
}
